import{_ as e,o as s,c as a,a as o}from"./app.DkoUFz-u.js";const _=JSON.parse('{"title":"print-server 服务排查与修复","description":"","frontmatter":{},"headers":[],"relativePath":"devops/container/docker/help.md","filePath":"devops/container/docker/help.md"}'),d={name:"devops/container/docker/help.md"};function n(r,t,i,c,l,p){return s(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="print-server-服务排查与修复" tabindex="-1">print-server 服务排查与修复 <a class="header-anchor" href="#print-server-服务排查与修复" aria-label="Permalink to &quot;print-server 服务排查与修复&quot;">​</a></h1><p><strong>项目</strong>: print-server（Fastify + Puppeteer 打印渲染服务） <strong>时间</strong>: 2026-07-08 <strong>场景</strong>: Docker 部署，主要使用 <code>/img</code> 截图接口</p><hr><h2 id="问题现象" tabindex="-1">问题现象 <a class="header-anchor" href="#问题现象" aria-label="Permalink to &quot;问题现象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>正常</th><th>异常</th></tr></thead><tbody><tr><td>容器 PIDs</td><td>低且稳定</td><td>持续增长（141 → <strong>249</strong>）</td></tr><tr><td>MEM USAGE</td><td>~50MiB</td><td><strong>274~283MiB</strong></td></tr><tr><td><code>/img</code> 接口</td><td>2s 返回</td><td><strong>6s 返回，部分超时</strong></td></tr></tbody></table><h2 id="排查过程" tabindex="-1">排查过程 <a class="header-anchor" href="#排查过程" aria-label="Permalink to &quot;排查过程&quot;">​</a></h2><h3 id="第一轮-pids-持续增长-—-定位孤儿进程泄漏" tabindex="-1">第一轮：PIDs 持续增长 — 定位孤儿进程泄漏 <a class="header-anchor" href="#第一轮-pids-持续增长-—-定位孤儿进程泄漏" aria-label="Permalink to &quot;第一轮：PIDs 持续增长 — 定位孤儿进程泄漏&quot;">​</a></h3><p><strong>现象确认</strong>：<code>docker exec</code> 进容器执行 <code>ps aux | grep -c chro</code> 返回 <strong>249</strong>，大量 <code>[chromium]</code> 僵尸进程。</p><p><strong>根因定位</strong>：<code>lib/puppeteer-html-export.js</code> 中 <code>screenshot()</code>、<code>createPdf()</code>、<code>htmlContent()</code> 三个方法在异常路径下不关闭浏览器。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_wvjl67">screenshot() →</span></span>\n<span class="line"><span class="__shiki_wvjl67">  setOptions() → puppeteer.launch()  ← 启动浏览器</span></span>\n<span class="line"><span class="__shiki_wvjl67">  getPage()    → browser.newPage()</span></span>\n<span class="line"><span class="__shiki_wvjl67">  waitGoToDomContentLoaded()         ← 可能抛超时异常</span></span>\n<span class="line"><span class="__shiki_wvjl67">  waitTemplateLoaded()               ← 可能抛超时异常</span></span>\n<span class="line"><span class="__shiki_wvjl67">  generateScreenshot()</span></span>\n<span class="line"><span class="__shiki_wvjl67">  closeBrowserIfNeeded()             ← ← ← 上面抛异常就不执行！</span></span></code></pre></div><p>每次超时泄漏 1 个 Chromium 进程（含子进程），累积到系统资源吃紧 → 新请求更容易超时 → 更多泄漏。<strong>恶性循环。</strong></p><p><strong>涉及文件</strong>：<code>lib/puppeteer-html-export.js</code></p><h3 id="第二轮-networkidle0-导致导航超时" tabindex="-1">第二轮：<code>networkidle0</code> 导致导航超时 <a class="header-anchor" href="#第二轮-networkidle0-导致导航超时" aria-label="Permalink to &quot;第二轮：`networkidle0` 导致导航超时&quot;">​</a></h3><p><code>waitGoToDomContentLoaded</code> 中使用 <code>waitUntil: [&quot;domcontentloaded&quot;, &quot;networkidle0&quot;]</code>，<code>networkidle0</code> 强制等待所有网络连接空闲才返回。页面加载大量外网 CDN 脚本时，这个条件非常苛刻，容易超时。</p><p><strong>修复</strong>：改为 <code>waitUntil: &quot;domcontentloaded&quot;</code>，DOM 就绪即返回，真正的等待由后续的 <code>waitTemplateLoaded()</code> 负责。</p><p><strong>涉及文件</strong>：<code>lib/puppeteer-html-export.js</code></p><h3 id="第三轮-docker-内部自访问-—-goto-耗时-5-7s" tabindex="-1">第三轮：Docker 内部自访问 — goto 耗时 5.7s <a class="header-anchor" href="#第三轮-docker-内部自访问-—-goto-耗时-5-7s" aria-label="Permalink to &quot;第三轮：Docker 内部自访问 — goto 耗时 5.7s&quot;">​</a></h3><p>线上 <code>/img</code> 返回 6.5s，本地只用 2s。单独测 <code>goto localhost</code> 只要 92ms。</p><p><strong>根因</strong>：路由中构造 URL 使用了 <code>request.hostname</code>（外网 IP），Puppeteer 从容器内访问外网 IP 回环到自身，经过 NAT 转发，耗时 5.7s。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">// 修复前</span></span>\n<span class="line"><span class="__shiki_1itgoe">const</span><span class="__shiki_dzsirb"> host</span><span class="__shiki_1itgoe"> =</span><span class="__shiki_mdbnqw"> `${</span><span class="__shiki_140thh">request</span><span class="__shiki_mdbnqw">.</span><span class="__shiki_140thh">protocol</span><span class="__shiki_mdbnqw">}://${</span><span class="__shiki_140thh">request</span><span class="__shiki_mdbnqw">.</span><span class="__shiki_140thh">hostname</span><span class="__shiki_mdbnqw">}`</span><span class="__shiki_140thh">;</span></span>\n<span class="line"><span class="__shiki_21nrsd">// 修复后</span></span>\n<span class="line"><span class="__shiki_1itgoe">const</span><span class="__shiki_dzsirb"> host</span><span class="__shiki_1itgoe"> =</span><span class="__shiki_mdbnqw"> `http://localhost:${</span><span class="__shiki_140thh">request</span><span class="__shiki_mdbnqw">.</span><span class="__shiki_140thh">socket</span><span class="__shiki_mdbnqw">.</span><span class="__shiki_140thh">localPort</span><span class="__shiki_1itgoe"> ||</span><span class="__shiki_dzsirb"> 3000</span><span class="__shiki_mdbnqw">}`</span><span class="__shiki_140thh">;</span></span></code></pre></div><p><strong>涉及文件</strong>：<code>routes/root.js</code></p><h2 id="修复清单" tabindex="-1">修复清单 <a class="header-anchor" href="#修复清单" aria-label="Permalink to &quot;修复清单&quot;">​</a></h2><h3 id="代码修复" tabindex="-1">代码修复 <a class="header-anchor" href="#代码修复" aria-label="Permalink to &quot;代码修复&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>修改</th><th>解决</th></tr></thead><tbody><tr><td><code>lib/puppeteer-html-export.js</code></td><td><code>screenshot()</code> 加 <code>try/finally</code></td><td>✅ 异常不泄漏浏览器</td></tr><tr><td><code>lib/puppeteer-html-export.js</code></td><td><code>createPdf()</code> 加 <code>try/finally</code></td><td>✅ 异常不泄漏浏览器</td></tr><tr><td><code>lib/puppeteer-html-export.js</code></td><td><code>htmlContent()</code> 加 <code>try/finally</code></td><td>✅ 异常不泄漏浏览器</td></tr><tr><td><code>lib/puppeteer-html-export.js</code></td><td><code>closeBrowserIfNeeded()</code> 加固</td><td>✅ 提前置 null + 5s超时 + 静默catch</td></tr><tr><td><code>lib/puppeteer-html-export.js</code></td><td><code>waitGoToDomContentLoaded</code> 去 <code>networkidle0</code></td><td>✅ 导航不依赖网络空闲</td></tr><tr><td><code>lib/puppeteer-html-export.js</code></td><td><code>getPage()</code> 加 <code>setDefaultNavigationTimeout()</code></td><td>✅ timeout 同步到 page</td></tr><tr><td><code>routes/root.js</code></td><td>构造 URL 改为 localhost</td><td>✅ 自访问从 5.7s → 0.4s</td></tr><tr><td><code>routes/root.js</code></td><td>timeout 60s → 120s</td><td>✅ 给渲染留足余量</td></tr></tbody></table><h3 id="dockerfile-优化" tabindex="-1">Dockerfile 优化 <a class="header-anchor" href="#dockerfile-优化" aria-label="Permalink to &quot;Dockerfile 优化&quot;">​</a></h3><p><code>msttcorefonts-installer</code> 从 SourceForge 下载极慢，改为从本地手动注入 <code>arial.ttf</code> 字体文件，构建时间从数分钟降到秒级。</p><h2 id="性能对比" tabindex="-1">性能对比 <a class="header-anchor" href="#性能对比" aria-label="Permalink to &quot;性能对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>修复前</th><th>修复后</th></tr></thead><tbody><tr><td><code>/img</code> 接口耗时</td><td><strong>6.5s</strong></td><td><strong>~1.2s</strong></td></tr><tr><td>goto 环节耗时</td><td><strong>5.7s</strong>（外网IP回环）</td><td><strong>~0.4s</strong>（localhost）</td></tr><tr><td>容器 PIDs</td><td>持续增长（最高 249）</td><td>回收稳定</td></tr><tr><td>内存占用</td><td>274~283MiB</td><td>~43MiB</td></tr></tbody></table><h2 id="遗留问题-后续优化" tabindex="-1">遗留问题 / 后续优化 <a class="header-anchor" href="#遗留问题-后续优化" aria-label="Permalink to &quot;遗留问题 / 后续优化&quot;">​</a></h2><ul><li><code>puppeteer.launch()</code> 固定 ~440ms（Docker 启动 Chromium 的成本），如需进一步提速可考虑浏览器连接池</li><li><code>msttcorefonts-installer</code> 移除后，模板中使用了 Microsoft 字体的需手动补 <code>arial.ttf</code> 等字体文件</li></ul>',30)])])}const u=e(d,[["render",n]]);export{_ as __pageData,u as default};
